  for (let b = 0; b < s.beats; b += 2) frames.push(s.start + b * BEAT_FRAMES + 7);
  frames.push(s.end - 1);
  const sub = path.join(dir, `${i + 1}-${s.id}`);
  mkdirSync(sub, {recursive: true});
  grab(frames, path.join(sub, '%03d.jpg'));
}
for (const f of CUT_FRAMES) grab([-3, -2, -1, 0, 1, 2].map(d => f + d), path.join(dir, `切点-${f}.jpg`), ',scale=640:360,tile=6x1:padding=4:color=gray');
console.log(dir);
// 导出拉伸、剪辑后的 bgm 单轨（未混合成配乐），供 check-bgm-grid.py 检查拍点是否落在成片的拍格上。
// 用法：node export-bgm-stem.mjs 输出路径.wav
import {writeFileSync} from 'node:fs';
import {loadBgm, toWav} from './music.mjs';

writeFileSync(process.argv[2], toWav(loadBgm()));
// 画面上的全部文字。中文与公式用标题字体 Songti SC Black；数值读数用正文字体 Menlo。

export const TEXT = {
  overture: {beats: ['一条曲线', '两个端点', '中间某一点', '切线和弦平行'], names: ['费马', '罗尔', '拉格朗日', '柯西'], chain: '四个定理，一条链', title: '微分中值定理', sub: '从费马到柯西', why: '为什么', ask: '曲线上总有这样一点？'},
  fermat: {title: '费马引理', peak: '最高点，切线是平的', valley: '最低点，也是平的', law: '极值处，导数为零'},
  rolle: {title: '罗尔定理', sub: ['两端一样高', '怎么弯都行', '中间总有平切线'], why: '最高点在中间', fermat: '用费马引理'},
  lagrange: {planes: ['两端', '不一样高', '斜着看'], parallel: '切线和弦平行', shear: '罗尔，加一个倾斜', title: '拉格朗日中值定理', meaning: '弦的斜率＝某点切线斜率'},
  cauchy: {together: '两个函数，一起随 t 走', parallel: '还是：切线和弦平行', lagrange: '令 g(x)=x，就是拉格朗日', title: '柯西中值定理'},
  chain: {names: ['费马', '罗尔', '拉格朗日', '柯西'], arrows: ['两端等高', '加一个倾斜', '换成参数'], root: '后三个都建在费马上', one: '四个定理，一个根源', flat: '极值处，切线是平的'},
};

export function allText() {
  const out = [];
  const walk = v => (typeof v === 'string' ? out.push(v) : Object.values(v).forEach(walk));
  walk(TEXT);
  return out;
}

