test('柯西：g′ 处处不为零，ξ 在区间内部，切线与弦平行', () => {
  for (let t = 0; t <= 1; t += 0.001) assert.ok(CAUCHY.dg(t) > 0.1);
  const t = CAUCHY.xi;
  assert.ok(t > 0.05 && t < 0.95);
  const dx = CAUCHY.g(1) - CAUCHY.g(0), dy = CAUCHY.f(1) - CAUCHY.f(0);
  assert.ok(Math.abs(CAUCHY.df(t) / CAUCHY.dg(t) - dy / dx) < 1e-6);
});

test('bgm：拉伸到 120 BPM，剪辑点在乐句首拍，段落落在切点上', () => {
  assert.equal(BGM.downbeatPhase, 0);
  assert.ok(Math.abs(BGM_STRETCH - BGM.period / 0.5) < 1e-12);
  assert.ok(BGM_STRETCH > 1.05 && BGM_STRETCH < 1.08, `拉伸倍数 ${BGM_STRETCH}`);
  for (const s of BGM_SEGMENTS) {
    assert.equal(s.from % 16, 0);
    assert.equal(s.at % 4, 0);
  }
  // bgm 第 32 拍起是正歌（前 32 拍能量低），落在费马的切点；第 176 拍起是间奏之后的第二段，落在柯西的切点
  const e = BGM.energyPer8Beats, mean = a => a.reduce((x, y) => x + y, 0) / a.length;
  assert.ok(e[4] > 1.2 * mean(e.slice(0, 4)));
  assert.ok(e[22] > 1.2 * mean(e.slice(18, 22)));
  assert.equal(bgmBeatAt(SCENES.find(s => s.id === 'fermat').beat), 32);
  assert.equal(bgmBeatAt(SCENES.find(s => s.id === 'cauchy').beat), 176);
  // 剪掉的一句前后和弦接得上：接缝后的小节是 F
  const seam = BGM_SEGMENTS[1];
  assert.equal(BGM.barChords[seam.from / 4].root, 5);
  // bgm 的结尾落在片尾最后 8 拍之内
  const endBeat = (BGM.duration - BGM.firstBeat) / BGM.period;
  const filmEnd = seam.at + (endBeat - seam.from);
  assert.ok(filmEnd > BEATS - 8 && filmEnd <= BEATS, `bgm 结束在第 ${filmEnd} 拍`);
});

const energy = (t, ms) => {
  const s = Math.round(t * SAMPLE_RATE), n = Math.round(ms * SAMPLE_RATE / 1000);
  let e = 0;
  for (let i = s; i < s + n; i++) e += MIX.left[i] ** 2 + MIX.right[i] ** 2;
  return e / n;
};

test('配乐：长度正确，不削顶，切点有明显起音，全程不断', () => {
  assert.equal(MIX.left.length, SAMPLE_RATE * SECONDS);
  let peak = 0;
  for (let i = 0; i < MIX.left.length; i++) peak = Math.max(peak, Math.abs(MIX.left[i]), Math.abs(MIX.right[i]));
  assert.ok(peak < 0.9, `峰值 ${peak}`);
  for (const b of [0, ...CUT_BEATS]) {
    const t = b * 0.5;
    const after = energy(t, 15);
    const before = t >= 0.05 ? energy(t - 0.035, 30) : 0;
    assert.ok(after > 3 * before, `第 ${b} 拍起音不明显：${after} vs ${before}`);
  }
  for (let s = 0; s < SECONDS - 1.5; s += 1) assert.ok(Math.sqrt(energy(s, 1000)) > 0.01, `第 ${s} 秒过静`);
});
import json
import sys

import librosa
import numpy as np

# 测量 bgm.mp3：拍长与第一拍（线性拟合 librosa 拍点）、小节首拍相位（低频起音按 4 拍相位比较）、
# 每 8 拍的能量、每小节和弦（chroma 三和弦模板）。结果写入 bgm-analysis.json，配乐按它拉伸、剪辑和定和弦。
# 用法：.agent/venv/bin/python 微分中值定理/短片/analyze-bgm.py bgm.mp3 微分中值定理/短片/bgm-analysis.json

src, dst = sys.argv[1], sys.argv[2]
y, sr = librosa.load(src, sr=22050, mono=True)
_, beats = librosa.beat.beat_track(y=y, sr=sr, units="frames", tightness=400)
bt = librosa.frames_to_time(beats, sr=sr)
idx = np.arange(len(bt))
period, first = np.polyfit(idx, bt, 1)
resid = bt - (period * idx + first)

S = np.abs(librosa.stft(y))
freqs = librosa.fft_frequencies(sr=sr)
low = librosa.onset.onset_strength(S=librosa.amplitude_to_db(S[freqs < 200]), sr=sr)
phase_low = [float(low[beats[p::4]].mean()) for p in range(4)]
downbeat_phase = int(np.argmax(phase_low))

rms = librosa.feature.rms(y=y)[0]
energy = []
for k in range(0, len(beats) - 8, 8):
    energy.append(round(float(rms[beats[k]:beats[k + 8]].mean()), 4))

names = ["C", "C#", "D", "Eb", "E", "F", "F#", "G", "Ab", "A", "Bb", "B"]
templates = []
for r in range(12):
    for q, iv in (("maj", (0, 4, 7)), ("min", (0, 3, 7))):
        t = np.zeros(12)
        for i in iv:
            t[(r + i) % 12] = 1
        templates.append((r, q, t / np.linalg.norm(t)))
y_h = librosa.effects.harmonic(y)
chroma = librosa.feature.chroma_cqt(y=y_h, sr=sr, hop_length=512)
times = librosa.frames_to_time(np.arange(chroma.shape[1]), sr=sr, hop_length=512)
chords = []
k = downbeat_phase
while True:
    a, b = first + k * period, first + (k + 4) * period
    m = (times >= a) & (times < b)
    if not m.any():
        break
    c = chroma[:, m].mean(axis=1)
    c = c / (np.linalg.norm(c) + 1e-9)
    r, q, _ = max(templates, key=lambda t: float(t[2] @ c))
    chords.append({"root": r, "quality": q, "name": names[r] + ("m" if q == "min" else "")})
    k += 4

out = {
    "source": src,
    "duration": round(len(y) / sr, 4),
    "period": float(period),
    "bpm": 60 / float(period),
    "firstBeat": float(first),
    "beatResidualMsMax": round(float(np.abs(resid).max() * 1000), 1),
    "beatResidualMsStd": round(float(resid.std() * 1000), 1),
    "beatCount": int(len(bt)),
    "downbeatPhase": downbeat_phase,
    "lowOnsetByPhase": [round(v, 3) for v in phase_low],
    "energyPer8Beats": energy,
    "barChords": chords,
}
with open(dst, "w") as f:
    json.dump(out, f, ensure_ascii=False, indent=1)
print(json.dumps({k: v for k, v in out.items() if k not in ("energyPer8Beats", "barChords")}, ensure_ascii=False))
print(" ".join(f"{i}:{c['name']}" for i, c in enumerate(chords)))
import json
import sys

import librosa
import numpy as np

# 检查剪辑后的 bgm 单轨：librosa 拍点到成片 0.5 秒拍格的偏差；小节首拍（低频起音最强的 4 拍相位）是否在成片小节首拍上；
# 接缝前后 4 拍的偏差。用法：.agent/venv/bin/python check-bgm-grid.py bgm单轨.wav 接缝拍号
y, sr = librosa.load(sys.argv[1], sr=22050, mono=True)
seam = int(sys.argv[2])
_, beats = librosa.beat.beat_track(y=y, sr=sr, units="frames", tightness=400, start_bpm=120)
bt = librosa.frames_to_time(beats, sr=sr)
grid = np.round(bt / 0.5).astype(int)
off = (bt - grid * 0.5) * 1000
S = np.abs(librosa.stft(y))
freqs = librosa.fft_frequencies(sr=sr)
low = librosa.onset.onset_strength(S=librosa.amplitude_to_db(S[freqs < 200]), sr=sr)
phase = [float(low[beats[grid % 4 == p]].mean()) for p in range(4)]
near = np.abs(grid - seam) <= 4
# 细测：hop 64（约 2.9 ms）的起音包络按 0.5 秒折叠，峰值相位就是 bgm 相对拍格的整体偏移
hop = 64
env = librosa.onset.onset_strength(y=y, sr=sr, hop_length=hop)
t = np.arange(len(env)) * hop / sr
bins = np.zeros(172)
for v, tt in zip(env, t):
    ph = ((tt + 0.25) % 0.5) - 0.25
    bins[int((ph + 0.25) / 0.5 * len(bins)) % len(bins)] += v
fold_ms = (np.argmax(bins) + 0.5) / len(bins) * 500 - 250
print(json.dumps({
    "foldedOffsetMs": round(float(fold_ms), 1),
    "beats": int(len(bt)),
    "offsetMsMedian": round(float(np.median(off)), 1),
    "offsetMsAbsP95": round(float(np.percentile(np.abs(off), 95)), 1),
    "offsetMsAbsMax": round(float(np.abs(off).max()), 1),
    "lowOnsetByFilmBarPhase": [round(v, 3) for v in phase],
    "downbeatOnFilmBar": int(np.argmax(phase)) == 0,
    "seamOffsetsMs": [[int(g), round(float(o), 1)] for g, o in zip(grid[near], off[near])],
}, indent=1))

