    else g.drawImage(img, 0, 0);
    return;
  }
  if (mode === 'in' && b < b0) return;
  if (mode === 'out' && b >= b1) return;
  const h = img.height / n, order = perm(seed, n), span = b1 - b0, each = span * 0.6, stagger = span - each;
