  line(g, x - k, y - k * m, x + k, y + k * m, color, width);
}
const fmt = v => (Math.abs(v) < 0.005 ? '0.00' : v.toFixed(2));

// ---------- 纸面与场景编号 ----------
let grain;
function paper(g) {
  g.setTransform(1, 0, 0, 1, 0, 0);
  g.globalAlpha = 1;
  g.fillStyle = PAPER;
  g.fillRect(0, 0, W, H);
