const energy = (t, ms) => {
  const s = Math.round(t * SAMPLE_RATE), n = Math.round(ms * SAMPLE_RATE / 1000);
  let e = 0;
  for (let i = s; i < s + n; i++) e += MIX.left[i] ** 2 + MIX.right[i] ** 2;
  return e / n;
};

