    const fs = s * 0.86;
    const num = layoutSeq(n.num, fs, color, tag), den = layoutSeq(n.den, fs, color, tag);
    const width = Math.max(num.w, den.w) + 0.24 * s, axis = 0.27 * s, th = 0.055 * s, gap = 0.13 * s;
    const box = emptyBox();
    append(box, num, (width - num.w) / 2, -(axis + th / 2 + gap + (num.ink?.y1 ?? 0)));
