  box.src = src;
  box.tags = {};
  for (const it of box.items) {
    const r = {x0: it.x + it.ink.x0, x1: it.x + it.ink.x1, y0: it.y + it.ink.y0, y1: it.y + it.ink.y1};
    if (it.tag) box.tags[it.tag] = unite(box.tags[it.tag], r);
