import {synthStem} from '../../../Tylor/短片/audio.mjs';
import {HIT_BEATS} from '../../../Tylor/短片/timeline.js';
const SR = 48000, syn = synthStem(), hp = new Float32Array(syn.left.length);
{ const k = Math.exp(-2 * Math.PI * 200 / SR); let lp = 0; for (let i = 0; i < hp.length; i++) { const m = (syn.left[i] + syn.right[i]) / 2; lp = (1 - k) * m + k * lp; hp[i] = m - lp; } }
const win = SR / 200;
const e = s => { let v = 0; for (let i = Math.max(0, s); i < s + win; i++) v += hp[i] ** 2; return v; };
for (const b of HIT_BEATS) { const c = Math.round(b * 0.5 * SR); let best = c, rise = -Infinity; for (let s = c - SR * 0.03; s <= c + SR * 0.03; s += SR / 1000) { const r = e(s) - e(s - win); if (r > rise) { rise = r; best = s; } } const o = Math.round((best - c) / SR * 1000); if (Math.abs(o) > 2) console.log(b, o); }
EOF
